import subprocess, pathlib
root = pathlib.Path.home() / ".claude"
skip = {"plugins", "projects", "jobs", "node_modules", "file-history", "shell-snapshots"}
def g(r, *a):
    return subprocess.run(["git", "-C", str(r), *a], capture_output=True, text=True).stdout.strip()
for gitdir in root.rglob(".git"):
    if any(p in skip for p in gitdir.relative_to(root).parts):
        continue
    r = gitdir.parent
    br = g(r, "branch", "--show-current")
    dirty = len([l for l in g(r, "status", "--porcelain").splitlines() if l])
    ahead = g(r, "rev-list", "--count", "@{u}..HEAD") or "?"
    if dirty or ahead != "0" or br not in ("main", "master"):
        print(f"{r} branch={br} dirty={dirty} ahead={ahead}")

